    public void testReflectionStatics() {
        final ReflectionStaticFieldsFixture instance1 = new ReflectionStaticFieldsFixture();

        final java.util.function.Function<String, String> canonicalize = s -> {
            final int start = s.indexOf('[');
            final int end = s.lastIndexOf(']');
            org.junit.jupiter.api.Assertions.assertTrue(start >= 0, s);
            org.junit.jupiter.api.Assertions.assertTrue(end >= start, s);
            org.junit.jupiter.api.Assertions.assertEquals(s.length() - 1, end, s);

            final String prefix = s.substring(0, start);
            final String fieldBody = s.substring(start + 1, end);
            final String[] fields = fieldBody.split(",", -1);

            for (final String field : fields) {
                org.junit.jupiter.api.Assertions.assertFalse(field.isEmpty(), s);
                final int equalsIndex = field.indexOf('=');
                org.junit.jupiter.api.Assertions.assertTrue(equalsIndex > 0, s);
                org.junit.jupiter.api.Assertions.assertEquals(field.lastIndexOf('='), equalsIndex, s);
            }

            final List<String> sortedFields = new ArrayList<>(java.util.Arrays.asList(fields));
            java.util.Collections.sort(sortedFields);
            return prefix + "[" + String.join(",", sortedFields) + "]";
        };

        assertEquals(
            canonicalize.apply(this.toBaseString(instance1) + "[staticString=staticString,staticInt=12345,instanceString=instanceString,instanceInt=67890]"),
            canonicalize.apply(ReflectionToStringBuilder.toString(instance1, null, false, true, ReflectionStaticFieldsFixture.class)));
        assertEquals(
            canonicalize.apply(this.toBaseString(instance1) + "[staticString=staticString,staticInt=12345,staticTransientString=staticTransientString,staticTransientInt=54321,instanceString=instanceString,instanceInt=67890,transientString=transientString,transientInt=98765]"),
            canonicalize.apply(ReflectionToStringBuilder.toString(instance1, null, true, true, ReflectionStaticFieldsFixture.class)));
        assertEquals(
            canonicalize.apply(this.toBaseString(instance1) + "[staticString=staticString,staticInt=12345,instanceString=instanceString,instanceInt=67890]"),
            canonicalize.apply(this.toStringWithStatics(instance1, null, ReflectionStaticFieldsFixture.class)));
        assertEquals(
            canonicalize.apply(this.toBaseString(instance1) + "[staticString=staticString,staticInt=12345,instanceString=instanceString,instanceInt=67890]"),
            canonicalize.apply(this.toStringWithStatics(instance1, null, ReflectionStaticFieldsFixture.class)));
    }

