public void testInheritedReflectionStatics() {
    final InheritedReflectionStaticFieldsFixture instance1 = new InheritedReflectionStaticFieldsFixture();

    final List<String> inheritedStaticFields = new ArrayList<>();
    inheritedStaticFields.add("staticString2=staticString2");
    inheritedStaticFields.add("staticInt2=67890");

    final List<String> allStaticFields = new ArrayList<>(inheritedStaticFields);
    allStaticFields.add("staticString=staticString");
    allStaticFields.add("staticInt=12345");

    final String prefix = this.toBaseString(instance1);

    final java.util.function.Function<String, String> normalize = actual -> {
        final int open = actual.indexOf('[');
        final int close = actual.lastIndexOf(']');
        final String actualPrefix = actual.substring(0, open);
        final String body = actual.substring(open + 1, close);
        final String suffix = actual.substring(close + 1);

        final List<String> entries = new ArrayList<>();
        if (!body.isEmpty()) {
            final String[] parts = body.split(",", -1);
            for (final String part : parts) {
                entries.add(part);
            }
        }
        java.util.Collections.sort(entries);

        final StringBuilder normalized = new StringBuilder(actualPrefix);
        normalized.append('[');
        for (int i = 0; i < entries.size(); i++) {
            if (i > 0) {
                normalized.append(',');
            }
            normalized.append(entries.get(i));
        }
        normalized.append(']');
        normalized.append(suffix);
        return normalized.toString();
    };

    final java.util.function.Function<List<String>, String> expected = entries -> {
        final List<String> sorted = new ArrayList<>(entries);
        java.util.Collections.sort(sorted);
        final StringBuilder expectedString = new StringBuilder(prefix);
        expectedString.append('[');
        for (int i = 0; i < sorted.size(); i++) {
            if (i > 0) {
                expectedString.append(',');
            }
            expectedString.append(sorted.get(i));
        }
        expectedString.append(']');
        return expectedString.toString();
    };

    assertEquals(
        expected.apply(inheritedStaticFields),
        normalize.apply(ReflectionToStringBuilder.toString(instance1, null, false, true, InheritedReflectionStaticFieldsFixture.class)));
    assertEquals(
        expected.apply(allStaticFields),
        normalize.apply(ReflectionToStringBuilder.toString(instance1, null, false, true, SimpleReflectionStaticFieldsFixture.class)));
    assertEquals(
        expected.apply(allStaticFields),
        normalize.apply(this.toStringWithStatics(instance1, null, SimpleReflectionStaticFieldsFixture.class)));
    assertEquals(
        expected.apply(allStaticFields),
        normalize.apply(this.toStringWithStatics(instance1, null, SimpleReflectionStaticFieldsFixture.class)));
}

