@Test
    public void stringArray() {
        final WithArrays wa = new WithArrays();
        wa.stringArray = new String[] { "a", "A" };

        final String actual = toString(wa);
        final String prefix = getClassPrefix(wa) + "[" + BR;
        final String suffix = BR + "]";

        assertEquals(prefix, actual.substring(0, prefix.length()));
        assertEquals(suffix, actual.substring(actual.length() - suffix.length()));

        final String body = actual.substring(prefix.length(), actual.length() - suffix.length());
        final String normalized = BR + body;

        final Pattern fieldPattern = Pattern.compile(Pattern.quote(BR) + "  ([A-Za-z_$][A-Za-z0-9_$]*)=");
        final Matcher matcher = fieldPattern.matcher(normalized);
        final List<Integer> starts = new ArrayList<>();
        final List<String> names = new ArrayList<>();
        while (matcher.find()) {
            starts.add(matcher.start());
            names.add(matcher.group(1));
        }

        assertEquals(0, starts.get(0).intValue());

        final Map<String, String> actualFields = new TreeMap<>();
        for (int i = 0; i < starts.size(); i++) {
            final int valueStart = normalized.indexOf('=', starts.get(i)) + 1;
            final int valueEnd = i + 1 < starts.size() ? starts.get(i + 1) : normalized.length();
            String value = normalized.substring(valueStart, valueEnd);
            if (i + 1 < starts.size()) {
                assertEquals(",", value.substring(value.length() - 1));
                value = value.substring(0, value.length() - 1);
            } else {
                assertFalse(value.endsWith(","));
            }
            actualFields.put(names.get(i), value);
        }
        assertEquals(names.size(), actualFields.size());

        final Map<String, String> expectedFields = new TreeMap<>();
        expectedFields.put("boolArray", "<null>");
        expectedFields.put("charArray", "<null>");
        expectedFields.put("intArray", "<null>");
        expectedFields.put("doubleArray", "<null>");
        expectedFields.put("longArray", "<null>");
        expectedFields.put("stringArray", "{"
                + BR + "    a,"
                + BR + "    A"
                + BR + "  }");

        assertEquals(expectedFields.size(), names.size());
        assertEquals(expectedFields, actualFields);
    }

