    Collections.sort(fields, new Comparator<Schema.Field>() {
      @Override
      public int compare(Schema.Field left, Schema.Field right) {
        return left.name().compareTo(right.name());
      }
    });

    StringBuilder canonicalActual = new StringBuilder();
    canonicalActual.append("{\"type\":\"").append(actualSchema.getType().getName())
        .append("\",\"name\":\"").append(actualSchema.getName())
        .append("\",\"namespace\":\"").append(actualSchema.getNamespace())
        .append("\",\"fields\":[");
    for (int i = 0; i < fields.size(); i++) {
      Schema.Field field = fields.get(i);
      if (i > 0) {
        canonicalActual.append(',');
      }
      canonicalActual.append("{\"name\":\"").append(field.name())
          .append("\",\"type\":\"").append(field.schema().getType().getName())
          .append("\"}");
    }
    canonicalActual.append("]}");

    assertEquals(
        "{\"type\":\"record\",\"name\":\"R\",\"namespace\":\"org.apache.avro.reflect.TestReflect\",\"fields\":["
            + "{\"name\":\"a\",\"type\":\"int\"}," + "{\"name\":\"b\",\"type\":\"long\"}]}",
        canonicalActual.toString());

    check(R.class, actualSchema.toString());
  }

