  public void testMultipleFieldAliases() {

    Schema expectedSchema = SchemaBuilder.record(ClassWithMultipleAliasesOnField.class.getSimpleName())
        .namespace("org.apache.avro.reflect.TestReflect").fields().name("primitiveField").aliases("alias1", "alias2")
        .type(Schema.create(org.apache.avro.Schema.Type.INT)).noDefault().endRecord();

    Schema actualSchema = ReflectData.get().getSchema(ClassWithMultipleAliasesOnField.class);

    Pattern aliasesPattern = Pattern.compile("(\"aliases\"\\s*:\\s*\\[)([^\\]]*)(\\])");

    String expectedSchemaString = expectedSchema.toString();
    StringBuffer expectedBuffer = new StringBuffer();
    Matcher expectedMatcher = aliasesPattern.matcher(expectedSchemaString);
    while (expectedMatcher.find()) {
      String[] rawAliases = expectedMatcher.group(2).split(",");
      List<String> aliases = new ArrayList<String>();
      for (String rawAlias : rawAliases) {
        aliases.add(rawAlias.trim());
      }
      Collections.sort(aliases);
      StringBuilder sortedAliases = new StringBuilder();
      for (int i = 0; i < aliases.size(); i++) {
        if (i > 0) {
          sortedAliases.append(",");
        }
        sortedAliases.append(aliases.get(i));
      }
      expectedMatcher.appendReplacement(expectedBuffer,
          Matcher.quoteReplacement(expectedMatcher.group(1) + sortedAliases + expectedMatcher.group(3)));
    }
    expectedMatcher.appendTail(expectedBuffer);

    String actualSchemaString = actualSchema.toString();
    StringBuffer actualBuffer = new StringBuffer();
    Matcher actualMatcher = aliasesPattern.matcher(actualSchemaString);
    while (actualMatcher.find()) {
      String[] rawAliases = actualMatcher.group(2).split(",");
      List<String> aliases = new ArrayList<String>();
      for (String rawAlias : rawAliases) {
        aliases.add(rawAlias.trim());
      }
      Collections.sort(aliases);
      StringBuilder sortedAliases = new StringBuilder();
      for (int i = 0; i < aliases.size(); i++) {
        if (i > 0) {
          sortedAliases.append(",");
        }
        sortedAliases.append(aliases.get(i));
      }
      actualMatcher.appendReplacement(actualBuffer,
          Matcher.quoteReplacement(actualMatcher.group(1) + sortedAliases + actualMatcher.group(3)));
    }
    actualMatcher.appendTail(actualBuffer);

    assertEquals(expectedBuffer.toString(), actualBuffer.toString());
  }

@Test
  public void testMultipleFieldAliases() throws Exception {

    Schema expectedSchema = SchemaBuilder.record(ClassWithMultipleAliasesOnField.class.getSimpleName())
        .namespace("org.apache.avro.reflect.TestReflect").fields().name("primitiveField").aliases("alias1", "alias2")
        .type(Schema.create(org.apache.avro.Schema.Type.INT)).noDefault().endRecord();

    Schema actualSchema = ReflectData.get().getSchema(ClassWithMultipleAliasesOnField.class);
    assertEquals(expectedSchema, actualSchema);

    Set<String> expectedAliases = new HashSet<String>(Arrays.asList("alias1", "alias2"));
    assertEquals(expectedAliases, actualSchema.getField("primitiveField").aliases());

    final ObjectMapper mapper = new ObjectMapper();
    JsonNode expectedNode = mapper.readTree(expectedSchema.toString());
    JsonNode actualNode = mapper.readTree(actualSchema.toString());

    Consumer<JsonNode> sortAliasArrays = new Consumer<JsonNode>() {
      @Override
      public void accept(JsonNode node) {
        if (node.isObject()) {
          ObjectNode objectNode = (ObjectNode) node;
          Iterator<String> fieldNames = objectNode.fieldNames();
          while (fieldNames.hasNext()) {
            String fieldName = fieldNames.next();
            JsonNode child = objectNode.get(fieldName);
            if ("aliases".equals(fieldName) && child.isArray()) {
              ArrayNode aliasesArray = (ArrayNode) child;
              List<String> aliases = new ArrayList<String>();
              Iterator<JsonNode> aliasElements = aliasesArray.elements();
              while (aliasElements.hasNext()) {
                aliases.add(aliasElements.next().asText());
              }
              Collections.sort(aliases);

              ArrayNode sortedAliases = mapper.createArrayNode();
              for (String alias : aliases) {
                sortedAliases.add(alias);
              }
              objectNode.set("aliases", sortedAliases);
              accept(objectNode.get(fieldName));
            } else {
              accept(child);
            }
          }
        } else if (node.isArray()) {
          ArrayNode arrayNode = (ArrayNode) node;
          Iterator<JsonNode> elements = arrayNode.elements();
          while (elements.hasNext()) {
            accept(elements.next());
          }
        }
      }
    };

    sortAliasArrays.accept(expectedNode);
    sortAliasArrays.accept(actualNode);

    assertEquals(expectedNode, actualNode);
  }

