public void test_f() throws Exception {
        String text = "parent.callback ({'id':1, 'name':'ido)nans'},1,2 );   /**/ ";

        JSONPObject jsonpObject = (JSONPObject) JSON.parseObject(text, JSONPObject.class);
        assertEquals("parent.callback", jsonpObject.getFunction());

        assertEquals(3, jsonpObject.getParameters().size());
        JSONObject param = (JSONObject) jsonpObject.getParameters().get(0);
        assertEquals(1, param.get("id"));
        assertEquals("ido)nans", param.get("name"));

        // Explicitly verify the underlying map type to kill the mutant that negates the 'ordered' flag
        assertTrue(param.getInnerMap() instanceof java.util.HashMap);
        assertFalse(param.getInnerMap() instanceof java.util.LinkedHashMap);

        String json = JSON.toJSONString(jsonpObject, SerializerFeature.BrowserSecure);
        assertTrue(json.startsWith("/**/parent.callback("));
        assertTrue(json.endsWith(",1,2)"));
        String innerJson = json.substring("/**/parent.callback(".length(), json.length() - ",1,2)".length());

        // Order-insensitive comparison to prevent flakiness from non-deterministic HashMap iteration
        JSONObject parsedInner = JSON.parseObject(innerJson);
        JSONObject expectedInner = new JSONObject();
        expectedInner.put("id", 1);
        expectedInner.put("name", "ido)nans");
        assertEquals(expectedInner, parsedInner);
    }

