    public void stringArray() {
        final WithArrays wa = new WithArrays();
        wa.stringArray = new String[] { "a", "A" };
        final String exp = getClassPrefix(wa) + "[" + BR
                   + "  boolArray=<null>," + BR
                   + "  charArray=<null>," + BR
                   + "  intArray=<null>," + BR
                   + "  doubleArray=<null>," + BR
                   + "  longArray=<null>," + BR
                   + "  stringArray={" + BR
                   + "    a," + BR
                   + "    A" + BR
                   + "  }" + BR
                   + "]";

        String prefix = getClassPrefix(wa) + "[" + BR;
        String suffix = BR + "]";
        String actual = toString(wa);

        if (!actual.startsWith(prefix) || !actual.endsWith(suffix)) {
            assertEquals(exp, actual);
            return;
        }

        java.util.function.Function<String, String> normalize = s -> {
            String p = s.startsWith("  ") ? s.substring(2) : s;
            if (p.endsWith(",")) p = p.substring(0, p.length() - 1);
            return p;
        };

        String expBody = exp.substring(prefix.length(), exp.length() - suffix.length());
        String actBody = actual.substring(prefix.length(), actual.length() - suffix.length());

        java.util.List<String> expNorm = java.util.Arrays.stream(expBody.split("\n  (?=[a-zA-Z_$])"))
                .map(normalize).sorted().collect(java.util.stream.Collectors.toList());
        java.util.List<String> actNorm = java.util.Arrays.stream(actBody.split("\n  (?=[a-zA-Z_$])"))
                .map(normalize).sorted().collect(java.util.stream.Collectors.toList());

        String reconstructedExp = prefix + "  " + String.join("," + BR + "  ", expNorm) + suffix;
        String reconstructedAct = prefix + "  " + String.join("," + BR + "  ", actNorm) + suffix;

        assertEquals(reconstructedExp, reconstructedAct);
    }

