    public void doubleArray() {
        final WithArrays wa = new WithArrays();
        wa.doubleArray = new double[] { 1, 2 };
        final String exp = getClassPrefix(wa) + "[" + BR
                   + "  boolArray=<null>," + BR
                   + "  charArray=<null>," + BR
                   + "  intArray=<null>," + BR
                   + "  doubleArray={" + BR
                   + "    1.0," + BR
                   + "    2.0" + BR
                   + "  }," + BR
                   + "  longArray=<null>," + BR
                   + "  stringArray=<null>" + BR
                   + "]";

        final Function<String, List<String>> toCanonicalFieldOrder = s -> {
            final String[] lines = s.split("\\R");
            final List<String> fieldBlocks = new ArrayList<>();
            List<String> currentBlock = new ArrayList<>();

            for (int i = 1; i < lines.length - 1; i++) {
                final String line = lines[i];
                if (line.matches("^  [^ ].*=.*")) {
                    if (!currentBlock.isEmpty()) {
                        String block = String.join(BR, currentBlock);
                        if (block.endsWith(",")) {
                            block = block.substring(0, block.length() - 1);
                        }
                        fieldBlocks.add(block);
                    }
                    currentBlock = new ArrayList<>();
                }
                currentBlock.add(line);
            }

            if (!currentBlock.isEmpty()) {
                String block = String.join(BR, currentBlock);
                if (block.endsWith(",")) {
                    block = block.substring(0, block.length() - 1);
                }
                fieldBlocks.add(block);
            }

            Collections.sort(fieldBlocks);

            final List<String> canonical = new ArrayList<>();
            canonical.add(lines[0]);
            canonical.addAll(fieldBlocks);
            canonical.add(lines[lines.length - 1]);
            return canonical;
        };

        assertEquals(toCanonicalFieldOrder.apply(exp), toCanonicalFieldOrder.apply(toString(wa)));
    }

